package io.karandash.api.finding

import kotlinx.serialization.Serializable

/**
 * A review thread karandash opened: the [botNote] holding the finding markers and the [refs] read from it.
 */
@Serializable
public data class InlineFindingThread(
    val thread: ReviewThread,
    val botNote: ReviewNote,
    val refs: List<InlineFindingRef>,
) {
    /** Head path of the thread's position, or the path its first finding names. */
    val path: String? get() = thread.position?.newPath ?: refs.firstOrNull()?.path

    /**
     * Notes a person added: not generated by the platform, not by the bot account that wrote [botNote], and not opening
     * with one of the [BOT_REPLY_MARKERS] (a bot reply counts as the bot's whoever the platform says wrote it). The bot
     * puts the marker on the first line, so a person's note that quotes a marker further down stays a human reply.
     */
    val humanReplies: List<ReviewNote>
        get() = thread.notes.filter { note ->
            !note.system &&
                note.id != botNote.id &&
                (note.author == null || note.author != botNote.author) &&
                BOT_REPLY_MARKERS.none { note.body.trimStart().startsWith(it) }
        }

    /** Whether a note written by the bot account that wrote [botNote] contains [marker]; a pasted marker does not count. */
    public fun hasBotNote(marker: String): Boolean = thread.notes.any { it.author == botNote.author && marker in it.body }

    public companion object {
        /** Marks the bot's help reply to an unknown `@karandash` command, so a thread gets it once. */
        public const val HELP_MARKER: String = "<!-- karandash-help -->"

        /** Marks the bot's "looks fixed" reply, so a thread gets it once. */
        public const val LOOKS_FIXED_MARKER: String = "<!-- karandash-looks-fixed -->"

        /** Marks the note the bot resolves a fixed thread with. */
        public const val FIXED_MARKER: String = "<!-- karandash-fixed -->"

        /** Start of the marker on the note the bot resolves a thread with for a `@karandash` command; the reply id follows. */
        public const val RESOLVED_BY_MARKER_PREFIX: String = "<!-- karandash-resolved-by:"

        /** Start of the marker on the bot's answer to a `@karandash why` or `ask` reply; the answered reply id follows. */
        public const val ANSWERED_MARKER_PREFIX: String = "<!-- karandash-answered:"

        /** Start of the marker on the bot's "cannot answer yet" reply to a `why` or `ask`; the reply id follows. It does not close the command. */
        public const val PENDING_MARKER_PREFIX: String = "<!-- karandash-pending:"

        /** Markers of the notes the bot adds to its own threads. */
        public val BOT_REPLY_MARKERS: List<String> =
            listOf(HELP_MARKER, LOOKS_FIXED_MARKER, FIXED_MARKER, RESOLVED_BY_MARKER_PREFIX, ANSWERED_MARKER_PREFIX, PENDING_MARKER_PREFIX)

        /** [thread] as a karandash thread, or null when no note of it carries finding markers. */
        public fun of(thread: ReviewThread): InlineFindingThread? = of(thread) { true }

        /**
         * [thread] as a karandash thread, or null when no note of it carries finding markers. Only a
         * note whose author [isBot] accepts can be the bot note.
         */
        public fun of(
            thread: ReviewThread,
            isBot: (String?) -> Boolean,
        ): InlineFindingThread? {
            val notes = thread.notes.filter { !it.system && isBot(it.author) }
            return notes.firstNotNullOfOrNull { note ->
                InlineFindingMarker.parse(note.body).ifEmpty { null }?.let { InlineFindingThread(thread, note, it) }
            }
        }

        /**
         * The karandash threads among [threads]. A marker note counts only when [botUsername] wrote it, or, when the
         * bot's identity is unknown, a project member ([isMember], asked once per author): a marker anyone else
         * pasted does not make a thread the bot's.
         */
        public suspend fun trustedOf(
            threads: List<ReviewThread>,
            botUsername: String?,
            isMember: suspend (String) -> Boolean,
        ): List<InlineFindingThread> {
            val trusted: Set<String> = if (botUsername != null) {
                setOf(botUsername)
            } else {
                threads
                    .flatMap { it.notes }
                    .filter { !it.system && InlineFindingMarker.carriesFindings(it.body) }
                    .mapNotNull { it.author }
                    .distinct()
                    .filter { isMember(it) }
                    .toSet()
            }
            return threads.mapNotNull { thread -> of(thread) { it != null && it in trusted } }
        }
    }
}
